    const game = activateCard(data.game, index);
    if (game === data.game) return;
    const result = turnAnnouncement(data.game, game);
    let best = data.best;
    const previous = best[game.board.size];
    if (isWon(game) && (previous === undefined || game.moves < previous)) {
